// Thumbnail cache for presets, favorites and variations. Thumbnails are generated by the
// same engine at low resolution in the worker pool and kept in memory only.

import { create } from 'zustand';
import type { MaterialSettings } from '../engine/types';
import { generateThumbnail, JobToken, Priority } from '../worker/client';

export interface Thumb {
  size: number;
  rgba: Uint8ClampedArray;
}

interface ThumbState {
  thumbs: Record<string, Thumb>;
  errors: Record<string, string>;
  request: (key: string, settings: MaterialSettings, size?: number, priority?: Priority) => void;
}

const inflight = new Set<string>();

export function settingsKey(s: MaterialSettings): string {
  const keys = Object.keys(s.params).sort();
  return `${s.family}|${s.seed}|${keys.map((k) => `${k}=${String(s.params[k])}`).join(',')}`;
}

export const useThumbs = create<ThumbState>((set, get) => ({
  thumbs: {},
  errors: {},
  request(key, settings, size = 128, priority = Priority.Normal) {
    if (get().thumbs[key] || inflight.has(key)) return;
    inflight.add(key);
    generateThumbnail(settings, size, new JobToken(), priority)
      .then(({ swatch }) => {
        set({ thumbs: { ...get().thumbs, [key]: { size, rgba: swatch } } });
      })
      .catch((e: unknown) => {
        set({ errors: { ...get().errors, [key]: e instanceof Error ? e.message : String(e) } });
      })
      .finally(() => inflight.delete(key));
  },
}));
